<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api/ehr';import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),items=ref([]);const canManage=computed(()=>['ADMIN','HR'].includes(auth.user?.role));const money=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2});const labels={DRAFT:'草稿',CONFIRMED:'已确认',PAID:'已发放'}
onMounted(async()=>items.value=canManage.value?await api.payroll():await api.payrollMine())
</script>
<template><div class="page safe-top"><van-nav-bar title="薪资记录" left-arrow @click-left="$router.back()"/><section class="privacy card"><van-icon name="shield-o" size="26"/><div><b>薪资数据已按角色隔离</b><p>员工仅能查看本人薪资，人事与管理员可维护全员数据。</p></div></section><section v-for="item in items" :key="item.id" class="salary card"><div class="salary-head"><div><b>{{item.payrollMonth}} 薪资</b><div v-if="canManage" class="muted">{{item.employeeName}}</div></div><span class="tag">{{labels[item.status]}}</span></div><div class="net"><small>实发工资</small><strong>¥ {{money(item.netSalary)}}</strong></div><div class="detail"><span>基本 ¥{{money(item.baseSalary)}}</span><span>津贴 ¥{{money(item.allowance)}}</span><span>奖金 ¥{{money(item.bonus)}}</span><span>扣款 ¥{{money(item.deduction)}}</span></div></section><div v-if="!items.length" class="empty">暂无薪资记录</div></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.privacy{display:flex;gap:14px;align-items:center;background:#fff8ef;color:#70452f}.privacy p{margin:5px 0 0;font-size:12px;opacity:.72}.salary-head{display:flex;justify-content:space-between}.net{padding:20px 0 15px}.net small{display:block;color:#978b84}.net strong{display:block;font-size:29px;margin-top:6px;color:#74452f}.detail{display:grid;grid-template-columns:1fr 1fr;gap:9px;color:#8c7c73;font-size:12px}</style>
